const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function translateText(text, context) {
  const prompt = `Du bist ein professioneller Deutschlehrer.
Der Schüler macht eine Übung.
Übungssatz: "${context}"
Deutscher Grammatik-Hinweis: "${text}"

Aufgabe: Übersetze diesen Grammatik-Hinweis ins Russische und Türkische, damit der Schüler ihn versteht.
Antworte NUR mit einem gültigen JSON-Objekt im folgenden Format (ohne Markdown Codeblöcke):
{"ru": "Russische Übersetzung", "tr": "Türkische Übersetzung"}
`;

  try {
    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${apiKey}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ role: "user", parts: [{ text: prompt }] }],
        generationConfig: {
          responseMimeType: "application/json",
          temperature: 0.1
        }
      })
    });

    if (!response.ok) {
      throw new Error(`API Error: ${response.status} - ${await response.text()}`);
    }

    const data = await response.json();
    const resultText = data.candidates[0].content.parts[0].text;
    return JSON.parse(resultText);
  } catch (error) {
    console.error("Translation Error:", error);
    return null;
  }
}

async function run() {
  console.log(`Starte Übersetzung für ${exercises.length} Einträge...`);
  let sqlQueries = `-- Automatisch generiertes Skript für Übersetzungen\n`;

  for (let i = 0; i < exercises.length; i++) {
    const ex = exercises[i];
    let contentObj;
    try {
      contentObj = JSON.parse(ex.content);
    } catch (e) { continue; }

    const hintText = contentObj.smart_hint?.de || contentObj.explanation?.de;
    if (!hintText) continue;
    
    // Fallback: If hint is manually set in the JSON (like in one of the examples)
    if (contentObj.smart_hint?.ru) {
      console.log(`[${i+1}/${exercises.length}] Überspringe (bereits übersetzt): ${ex.id}`);
      continue;
    }

    let sentence = "";
    if (ex.type === "fill_in_blank") {
      sentence = (contentObj.text_before || "") + "___" + (contentObj.text_after || "");
    } else if (ex.type === "multiple_choice") {
      sentence = contentObj.question || "";
    }

    console.log(`[${i+1}/${exercises.length}] Übersetze: ${ex.id}`);
    
    const translations = await translateText(hintText, sentence);
    if (!translations) {
      console.log("Fehler bei Übersetzung, warte 5s...");
      await sleep(5000);
      continue;
    }

    // Update the content object
    if (contentObj.smart_hint?.de) {
      contentObj.smart_hint.ru = translations.ru;
      contentObj.smart_hint.tr = translations.tr;
    }
    if (contentObj.explanation?.de) {
      contentObj.explanation.ru = translations.ru;
      contentObj.explanation.tr = translations.tr;
    }

    // Escape single quotes for SQL
    const updatedContentJson = JSON.stringify(contentObj).replace(/'/g, "''");

    sqlQueries += `UPDATE public.exercises SET content = '${updatedContentJson}'::jsonb WHERE id = '${ex.id}';\n`;
    
    // Rate limit waiting
    await sleep(2000);
  }

  const outputPath = path.join(__dirname, '..', 'supabase', 'migrations', '20260911000001_translate_grammar_hints.sql');
  fs.writeFileSync(outputPath, sqlQueries);
  console.log(`✅ Fertig! SQL-Skript wurde generiert unter: ${outputPath}`);
}

run();
